 10	namespace RuneshapePriceChecker.Runes;
 11	
 12	/// <summary>
 13	/// The rune library: the shipped list of 34 runeshapes (names, effects, tiers, default
 14	/// weights, reference glyphs) plus the user layer beside the exe —
 15	/// <c>config/rune-catalog.json</c> — holding weight overrides, sprite bindings and the
 16	/// carried-this-run set. Thread-safe; every mutation bumps <see cref="Revision"/>, raises
 17	/// <see cref="Changed"/> and schedules a debounced save.
 18	///
 19	/// Sprites are <b>bound</b>, not discovered: a gilded key the detector reports is matched
 20	/// to an existing binding on shape alone (see <see cref="RuneKeyMatcher"/>); an unmatched
 21	/// key is held in memory on its first sighting and persisted as an <i>unbound</i> binding
 22	/// on its second (a one-frame OCR artefact never reaches disk), capped by
 23	/// <see cref="RunesOptions.MaxUnboundBindings"/>. The user then picks which rune it is.
 24	/// </summary>
 25	public sealed class RuneCatalog : IDisposable
 26	{
 27	    private static readonly JsonSerializerOptions JsonOptions = new()
 28	    {
 29	        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
 30	        PropertyNameCaseInsensitive = true,
 31	        WriteIndented = true,
 32	        DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull
 33	    };
 34	
 35	    private static readonly TimeSpan SaveDebounce = TimeSpan.FromSeconds(2);
 36	
 37	    private readonly object _sync = new();
 38	    private readonly IOptionsMonitor<RunesOptions> _options;
 39	    private readonly ILogger _logger;
 40	    private readonly string _userFilePath;
 41	    private readonly List<RuneDefinition> _runes;
 42	    private readonly Dictionary<string, RuneDefinition> _runesById;
 43	    private readonly Dictionary<string, double> _weightOverrides = new(StringComparer.OrdinalIgnoreCase);
 44	    private readonly List<RuneBinding> _bindings = [];
 45	    private readonly Dictionary<ulong, RuneBinding> _pending = [];
 46	    private readonly HashSet<string> _carried = new(StringComparer.OrdinalIgnoreCase);
 47	    private long _revision;
 48	    private bool _dirty;
 49	    private bool _warnedCap;
 50	    private System.Threading.Timer? _saveTimer;
 51	
 52	    public RuneCatalog(IOptionsMonitor<RunesOptions> options, ILogger<RuneCatalog> logger)
 53	        : this(options, logger, DefaultUserFilePath, LoadShippedJson())
 54	    {
 55	    }
 56	
 57	    internal RuneCatalog(IOptionsMonitor<RunesOptions> options, ILogger logger, string userFilePath, string shippedJson)
 58	    {
 59	        _options = options;
 60	        _logger = logger;
 61	        _userFilePath = userFilePath;
 62	
 63	        var shipped = JsonSerializer.Deserialize<RuneCatalogShipped>(shippedJson, JsonOptions) ?? new RuneCatalogShipped();
 64	        _runes = shipped.Runes.Where(r => !string.IsNullOrWhiteSpace(r.Id)).ToList();
 65	        _runesById = _runes.ToDictionary(r => r.Id, StringComparer.OrdinalIgnoreCase);
 66	        LoadUserLayer();
 67	    }
 68	
 69	    public static string DefaultUserFilePath => Path.Combine(AppContext.BaseDirectory, "config", "rune-catalog.json");
 70	
 71	    /// <summary>Raised (outside the lock) after any change that affects scoring or the library view.</summary>
 72	    public event Action? Changed;
 73	
 74	    /// <summary>Monotonic counter bumped on every mutation; re-render hashes include it.</summary>
 75	    public long Revision { get { lock (_sync) return _revision; } }
 76	
 77	    public IReadOnlyList<RuneDefinition> Runes => _runes;
 78	
 79	    /// <summary>Persisted bindings (bound and unbound). First-sighting pending keys are not included.</summary>
 80	    public IReadOnlyList<RuneBinding> Bindings { get { lock (_sync) return _bindings.Select(Clone).ToList(); } }
 81	
 82	    public IReadOnlyCollection<string> Carried { get { lock (_sync) return _carried.ToList(); } }
 83	
 84	    public RuneDefinition? GetRune(string? id)
 85	    {
 86	        if (string.IsNullOrEmpty(id)) return null;
 87	        return _runesById.TryGetValue(id, out var rune) ? rune : null;
 88	    }
 89	
 90	    public double GetWeight(string runeId)
 91	    {
 92	        lock (_sync)
 93	        {
 94	            if (_weightOverrides.TryGetValue(runeId, out var w)) return w;
 95	        }
 96	        return GetRune(runeId)?.Weight ?? _options.CurrentValue.UnknownRuneWeight;
 97	    }
 98	
 99	    public void SetWeight(string runeId, double weight)
100	    {
101	        if (GetRune(runeId) is null) return;
102	        lock (_sync)
103	        {
104	            var shipped = _runesById[runeId].Weight;
105	            if (Math.Abs(shipped - weight) < 1e-9) _weightOverrides.Remove(runeId);
106	            else _weightOverrides[runeId] = weight;
107	            TouchLocked();
108	        }
109	        Changed?.Invoke();
110	    }
111	
112	    /// <summary>Weight for an unbound sprite from its glyph hue alone. Gold (weight 3) is never reachable this way.</summary>
113	    public double UnboundWeight(int hueBucket)
114	    {
115	        var o = _options.CurrentValue;
116	        return hueBucket switch
117	        {
118	            6 or 7 => o.BlueTierWeight,
119	            8 or 9 => o.PurpleTierWeight,
120	            _ => o.UnknownRuneWeight
121	        };
122	    }
123	
124	    public RuneBinding? FindBinding(ulong shapeHash)
125	    {
126	        lock (_sync) return FindBindingLocked(shapeHash) is { } b ? Clone(b) : null;
127	    }
128	
129	    private RuneBinding? FindBindingLocked(ulong shapeHash)
130	    {
131	        var threshold = _options.CurrentValue.MatchHammingThreshold;
132	        return RuneKeyMatcher.FindNearest(shapeHash, _bindings, b => b.ShapeHash, threshold)
133	            ?? RuneKeyMatcher.FindNearest(shapeHash, _pending.Values, b => b.ShapeHash, threshold);
134	    }
135	
136	    /// <summary>Records a sighting. Returns true when the persisted state changed.</summary>
137	    public bool Observe(RuneKey key, DateTimeOffset? now = null)
138	    {
139	        ArgumentNullException.ThrowIfNull(key);
140	        var at = now ?? DateTimeOffset.UtcNow;
141	        var changed = false;
142	        lock (_sync)
143	        {
144	            var existing = FindBindingLocked(key.ShapeHash);
145	            if (existing is null)
146	            {
147	                _pending[key.ShapeHash] = new RuneBinding
148	                {
149	                    Id = RuneBinding.IdFor(key.ShapeHash),
150	                    ShapeHash = key.ShapeHash,
151	                    HueBucket = key.HueBucket,
152	                    SpritePngBase64 = SpriteCodec.ToPngBase64(key.Sprite32Rgb),
153	                    SeenCount = 1,
154	                    FirstSeenUtc = at,
155	                    LastSeenUtc = at
156	                };
157	            }
158	            else if (_pending.ContainsKey(existing.ShapeHash) && !_bindings.Contains(existing))
159	            {
160	                // Second sighting of a pending key: promote to the persisted layer (bounded).
161	                var unbound = _bindings.Count(b => !b.IsBound);
162	                if (unbound >= _options.CurrentValue.MaxUnboundBindings)
163	                {
164	                    if (!_warnedCap)
165	                    {
166	                        _warnedCap = true;
167	                        _logger.LogWarning("RuneCatalog: {Cap} unbound sprites already stored; new sprites are ignored until some are bound", unbound);
168	                    }
169	                    existing.SeenCount++;
170	                    existing.LastSeenUtc = at;
171	                }
172	                else
173	                {
174	                    _pending.Remove(existing.ShapeHash);
175	                    existing.SeenCount++;
176	                    existing.LastSeenUtc = at;
177	                    existing.HueBucket = key.HueBucket;
178	                    _bindings.Add(existing);
179	                    TouchLocked();
180	                    changed = true;
181	                }
182	            }
183	            else
184	            {
185	                existing.SeenCount++;
186	                existing.LastSeenUtc = at;
187	                existing.HueBucket = key.HueBucket;
188	                _dirty = true;
189	                ScheduleSaveLocked();
190	            }
191	        }
192	        if (changed) Changed?.Invoke();
193	        return changed;
194	    }
195	
196	    /// <summary>Binds a stored sprite to a rune (<paramref name="runeId"/> null unbinds). The carried set follows the binding.</summary>
197	    public bool Bind(string bindingId, string? runeId)
198	    {
199	        if (runeId is not null && GetRune(runeId) is null) return false;
200	        lock (_sync)
201	        {
202	            var binding = _bindings.FirstOrDefault(b => string.Equals(b.Id, bindingId, StringComparison.OrdinalIgnoreCase));
203	            if (binding is null) return false;
204	
205	            var previousCarriedId = binding.IsBound ? binding.RuneId! : binding.Id;
206	            binding.RuneId = runeId;
207	            var newCarriedId = runeId ?? binding.Id;
208	            if (_carried.Remove(previousCarriedId)) _carried.Add(newCarriedId);
209	            TouchLocked();
210	        }
211	        Changed?.Invoke();
212	        return true;
213	    }
214	
215	    /// <summary>Forgets a stored sprite entirely.</summary>
216	    public bool RemoveBinding(string bindingId)
217	    {
218	        lock (_sync)
219	        {
220	            var removed = _bindings.RemoveAll(b => string.Equals(b.Id, bindingId, StringComparison.OrdinalIgnoreCase));
221	            if (removed == 0) return false;
222	            _carried.Remove(bindingId);
223	            TouchLocked();
224	        }
225	        Changed?.Invoke();
226	        return true;
227	    }
228	
229	    /// <summary>The id a key is carried under: its rune id when bound, else its binding id.</summary>
230	    public static string CarriedIdFor(RuneBinding binding) => binding.IsBound ? binding.RuneId! : binding.Id;
231	
232	    public bool IsCarried(string id) { lock (_sync) return _carried.Contains(id); }
233	
234	    public void SetCarried(string id, bool carried)
235	    {
236	        lock (_sync)
237	        {
238	            var changed = carried ? _carried.Add(id) : _carried.Remove(id);
239	            if (!changed) return;
240	            TouchLocked();
241	        }
242	        Changed?.Invoke();
243	    }
244	
245	    public void ResetCarried()
246	    {
247	        lock (_sync)
248	        {
249	            if (_carried.Count == 0) return;
250	            _carried.Clear();
251	            TouchLocked();
252	        }
253	        Changed?.Invoke();
254	    }
255	
256	    /// <summary>
257	    /// Resolves a detected key to what the scorer needs: its binding (persisted or pending),
258	    /// the rune it is bound to (if any) and the weight — the rune's weight when bound, else the
259	    /// hue-rule weight for an unbound sprite.
260	    /// </summary>
261	    public RuneResolution Resolve(RuneKey key)
262	    {
263	        ArgumentNullException.ThrowIfNull(key);
264	        RuneBinding? binding;
265	        lock (_sync) binding = FindBindingLocked(key.ShapeHash) is { } b ? Clone(b) : null;
266	
267	        var bindingId = binding?.Id ?? RuneBinding.IdFor(key.ShapeHash);
268	        var rune = GetRune(binding?.RuneId);
269	        var carriedId = rune?.Id ?? bindingId;
270	        var weight = rune is not null ? GetWeight(rune.Id) : UnboundWeight(key.HueBucket);
271	        return new RuneResolution(bindingId, rune, weight, IsCarried(carriedId), carriedId);
272	    }
273	
274	    /// <summary>Writes pending changes now (also runs on dispose).</summary>
275	    public void Flush()
276	    {
277	        lock (_sync)
278	        {
279	            _saveTimer?.Change(Timeout.Infinite, Timeout.Infinite);
280	            if (!_dirty) return;
281	            SaveLocked();
282	        }
283	    }
284	
285	    public void Dispose()
286	    {
287	        Flush();
288	        lock (_sync)
289	        {
290	            _saveTimer?.Dispose();
291	            _saveTimer = null;
292	        }
293	    }
294	
295	    private void TouchLocked()
296	    {
297	        _revision++;
298	        _dirty = true;
299	        ScheduleSaveLocked();
300	    }
301	
302	    private void ScheduleSaveLocked()
303	    {
304	        _saveTimer ??= new System.Threading.Timer(_ => Flush(), null, Timeout.Infinite, Timeout.Infinite);
305	        _ = _saveTimer.Change(SaveDebounce, Timeout.InfiniteTimeSpan);
306	    }
307	
308	    private void SaveLocked()
309	    {
310	        try
311	        {
312	            var layer = new RuneCatalogUserLayer
313	            {
314	                Revision = _revision,
315	                Weights = new Dictionary<string, double>(_weightOverrides, StringComparer.OrdinalIgnoreCase),
316	                Bindings = _bindings.Select(Clone).ToList(),
317	                Carried = _carried.OrderBy(c => c, StringComparer.OrdinalIgnoreCase).ToList()
318	            };
319	            var dir = Path.GetDirectoryName(_userFilePath);
320	            if (!string.IsNullOrEmpty(dir)) _ = Directory.CreateDirectory(dir);
321	            var tmp = _userFilePath + ".tmp";
322	            File.WriteAllText(tmp, JsonSerializer.Serialize(layer, JsonOptions) + Environment.NewLine);
323	            File.Move(tmp, _userFilePath, overwrite: true);
324	            _dirty = false;
325	        }
326	        catch (Exception ex)
327	        {
328	            _logger.LogWarning(ex, "RuneCatalog: failed to save {Path}", _userFilePath);
329	        }
330	    }
331	
332	    private void LoadUserLayer()
333	    {
334	        if (!File.Exists(_userFilePath)) return;
335	        try
336	        {
337	            var layer = JsonSerializer.Deserialize<RuneCatalogUserLayer>(File.ReadAllText(_userFilePath), JsonOptions);
338	            if (layer is null) return;
339	            _revision = layer.Revision;
340	            foreach (var (id, weight) in layer.Weights)
341	                if (_runesById.ContainsKey(id)) _weightOverrides[id] = weight;
342	            foreach (var binding in layer.Bindings)
343	            {
344	                if (string.IsNullOrEmpty(binding.Id)) binding.Id = RuneBinding.IdFor(binding.ShapeHash);
345	                if (binding.RuneId is not null && !_runesById.ContainsKey(binding.RuneId)) binding.RuneId = null;
346	                _bindings.Add(binding);
347	            }
348	            foreach (var id in layer.Carried) _carried.Add(id);
349	        }
350	        catch (Exception ex)
351	        {
352	            _logger.LogWarning(ex, "RuneCatalog: could not read {Path}; starting with shipped defaults", _userFilePath);
353	        }
354	    }
355	
356	    private static RuneBinding Clone(RuneBinding b) => new()
357	    {
358	        Id = b.Id,
359	        ShapeHash = b.ShapeHash,
360	        HueBucket = b.HueBucket,
361	        SpritePngBase64 = b.SpritePngBase64,
362	        RuneId = b.RuneId,
363	        SeenCount = b.SeenCount,
364	        FirstSeenUtc = b.FirstSeenUtc,
365	        LastSeenUtc = b.LastSeenUtc
366	    };
367	
368	    /// <summary>Loads the embedded <c>ocr/rune-catalog.json</c>, same lookup as the unique-category map.</summary>
369	    internal static string LoadShippedJson()
370	    {
371	        try
372	        {
373	            var asm = Assembly.GetExecutingAssembly();
374	            var name = asm.GetManifestResourceNames()
375	                .FirstOrDefault(n => n.EndsWith("rune-catalog.json", StringComparison.OrdinalIgnoreCase));
376	            if (name is not null)
377	            {
378	                using var stream = asm.GetManifestResourceStream(name);
379	                using var reader = new StreamReader(stream!);
380	                return reader.ReadToEnd();
381	            }
382	
383	            var projectDir = Path.Combine(AppContext.BaseDirectory, "..", "..", "..");
384	            var filePath = Path.Combine(projectDir, "ocr", "rune-catalog.json");
385	            if (File.Exists(filePath)) return File.ReadAllText(filePath);
386	        }
387	        catch
388	        {
389	        }
390	        return """{"schema":1,"runes":[]}""";
391	    }
392	
393	    /// <summary>Reads an embedded reference glyph (<c>ocr/rune-icons/&lt;id&gt;.png</c>) as PNG bytes, or null.</summary>
394	    public static byte[]? LoadReferenceIcon(string? iconName)
395	    {
396	        if (string.IsNullOrWhiteSpace(iconName)) return null;
397	        try
398	        {
399	            var asm = Assembly.GetExecutingAssembly();
400	            // MSBuild sanitises folder names in manifest resource names (rune-icons → rune_icons),
401	            // so match on the file name and the folder in either spelling.
402	            var name = asm.GetManifestResourceNames()
403	                .FirstOrDefault(n => n.EndsWith("." + iconName, StringComparison.OrdinalIgnoreCase)
