427	/// <summary>PNG encoding for the detector's 32×32 RGB24 sprites.</summary>
428	public static class SpriteCodec
429	{
430	    public const int SpriteSize = 32;
431	
432	    public static string? ToPngBase64(byte[]? rgb)
433	    {
434	        if (rgb is null || rgb.Length < SpriteSize * SpriteSize * 3) return null;
435	        try
436	        {
437	            using var bmp = new Bitmap(SpriteSize, SpriteSize, PixelFormat.Format24bppRgb);
438	            var rect = new Rectangle(0, 0, SpriteSize, SpriteSize);
439	            var data = bmp.LockBits(rect, ImageLockMode.WriteOnly, PixelFormat.Format24bppRgb);
440	            try
441	            {
442	                var row = new byte[SpriteSize * 3];
443	                for (var y = 0; y < SpriteSize; y++)
444	                {
445	                    for (var x = 0; x < SpriteSize; x++)
446	                    {
447	                        var si = ((y * SpriteSize) + x) * 3;
448	                        row[(x * 3)] = rgb[si + 2];     // B
449	                        row[(x * 3) + 1] = rgb[si + 1]; // G
450	                        row[(x * 3) + 2] = rgb[si];     // R
451	                    }
452	                    Marshal.Copy(row, 0, data.Scan0 + (y * data.Stride), row.Length);
453	                }
454	            }
455	            finally
456	            {
457	                bmp.UnlockBits(data);
458	            }
459	            using var ms = new MemoryStream();
460	            bmp.Save(ms, ImageFormat.Png);
461	            return Convert.ToBase64String(ms.ToArray());
462	        }
