196	    /// <summary>Binds a stored sprite to a rune (<paramref name="runeId"/> null unbinds). The carried set follows the binding.</summary>
197	    public bool Bind(string bindingId, string? runeId)
198	    {
199	        if (runeId is not null && GetRune(runeId) is null) return false;
200	        lock (_sync)
201	        {
202	            var binding = _bindings.FirstOrDefault(b => string.Equals(b.Id, bindingId, StringComparison.OrdinalIgnoreCase));
203	            if (binding is null) return false;
