 10	namespace RuneshapePriceChecker.Overlay;
 11	
 12	/// <summary>One frame to draw: a gilded cell in capture-region coordinates and how to mark it.</summary>
 13	public sealed record RuneMarker(Rectangle Cell, RuneMarkerKind Kind, bool IsTopPick, bool IsUnbound);
 14	
 15	public enum CarriedMarkerStyle
 16	{
 17	    /// <summary>Grey frame plus a diagonal slash (default).</summary>
 18	    Slash,
 19	    /// <summary>Red frame plus an X.</summary>
 20	    Cross,
 21	    /// <summary>Darken the icon only, no frame.</summary>
 22	    Dim
 23	}
 24	
 25	/// <summary>
 26	/// Pure drawing of rune markers, kept separate from the window so it can be exercised on an
 27	/// offscreen bitmap in tests. Frames sit just outside the cell's drawn rectangle (gold frame
 28	/// included) so they never cover the glyph; thickness scales with the cell so the same look
 29	/// holds at every capture profile.
 30	/// </summary>
 31	public static class RuneMarkerPainter
 32	{
 33	    public static readonly Color CarriedColor = Color.FromArgb(154, 154, 154);
 34	    public static readonly Color CarriedCrossColor = Color.FromArgb(255, 72, 72);
 35	    public static readonly Color ValuableColor = Color.FromArgb(88, 255, 122);
 36	    public static readonly Color HighValueColor = Color.FromArgb(255, 160, 64);
 37	    public static readonly Color BadgeGold = Color.FromArgb(255, 224, 102);
 38	    public static readonly Color BadgeAmber = Color.FromArgb(245, 197, 66);
 39	    private static readonly Color BadgeBack = Color.FromArgb(230, 27, 27, 27);
 40	
 41	    public static Color ColorFor(RuneMarkerKind kind, CarriedMarkerStyle style) => kind switch
 42	    {
 43	        RuneMarkerKind.Carried => style == CarriedMarkerStyle.Cross ? CarriedCrossColor : CarriedColor,
 44	        RuneMarkerKind.HighValue => HighValueColor,
 45	        _ => ValuableColor
 46	    };
 47	
 48	    /// <summary>3 px at the 45 px cells of 2560x1440, never thinner than 2 px.</summary>
 49	    public static int FrameThickness(Rectangle cell) => Math.Max(2, (int)Math.Round(3.0 * cell.Height / 45.0));
 50	
 51	    public static CarriedMarkerStyle ParseStyle(string? text) => text?.Trim().ToLowerInvariant() switch
 52	    {
 53	        "cross" or "x" => CarriedMarkerStyle.Cross,
 54	        "dim" => CarriedMarkerStyle.Dim,
 55	        _ => CarriedMarkerStyle.Slash
 56	    };
 57	
 58	    public static IReadOnlyList<RuneMarker> FromSheet(RuneScoreSheet sheet)
 59	    {
 60	        ArgumentNullException.ThrowIfNull(sheet);
 61	        var markers = new List<RuneMarker>();
 62	        foreach (var key in sheet.AllKeys)
 63	        {
 64	            var cell = key.Key.CellBounds;
 65	            if (cell.Width <= 0 || cell.Height <= 0) continue;
 66	            markers.Add(new RuneMarker(cell, key.Marker, key.IsTopPick, key.IsUnbound));
 67	        }
 68	        return markers;
 69	    }
 70	
 71	    public static void Paint(Graphics g, IReadOnlyList<RuneMarker> markers, CarriedMarkerStyle style)
 72	    {
 73	        ArgumentNullException.ThrowIfNull(g);
 74	        ArgumentNullException.ThrowIfNull(markers);
 75	
 76	        g.SmoothingMode = SmoothingMode.AntiAlias;
 77	        g.PixelOffsetMode = PixelOffsetMode.HighQuality;
 78	        g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;
 79	
 80	        foreach (var marker in markers)
 81	        {
 82	            var cell = marker.Cell;
 83	            var t = FrameThickness(cell);
 84	            var color = ColorFor(marker.Kind, style);
 85	
 86	            if (marker.Kind == RuneMarkerKind.Carried && style == CarriedMarkerStyle.Dim)
 87	            {
 88	                using var dim = new SolidBrush(Color.FromArgb(120, 0, 0, 0));
 89	                g.FillRectangle(dim, cell);
 90	            }
 91	            else
 92	            {
 93	                // The frame band occupies [cell.X - t, cell.X) on the left and [cell.Right, cell.Right + t)
 94	                // on the right (same vertically). The pen is centred on the path, so the path runs
 95	                // through the middle of that band: half a thickness outside the cell edge.
 96	                var half = t / 2f;
 97	                using var pen = new Pen(color, t) { LineJoin = LineJoin.Miter, Alignment = PenAlignment.Center };
 98	                g.DrawRectangle(pen, cell.X - half, cell.Y - half, cell.Width + t, cell.Height + t);
 99	
100	                if (marker.Kind == RuneMarkerKind.Carried)
101	                {
102	                    using var strike = new Pen(color, Math.Max(2, t)) { StartCap = LineCap.Round, EndCap = LineCap.Round };
103	                    var inset = t;
104	                    g.DrawLine(strike, cell.Left + inset, cell.Bottom - inset, cell.Right - inset, cell.Top + inset);
105	                    if (style == CarriedMarkerStyle.Cross)
106	                        g.DrawLine(strike, cell.Left + inset, cell.Top + inset, cell.Right - inset, cell.Bottom - inset);
107	                }
108	            }
109	
110	            var r = Math.Max(7, (int)Math.Round(cell.Height * 0.2));
111	            if (marker.IsUnbound)
112	                DrawBadge(g, new Point(cell.Left - (r / 2), cell.Top - (r / 2)), r, "?", BadgeAmber);
113	            if (marker.IsTopPick)
114	                DrawBadge(g, new Point(cell.Right - (r * 3 / 2), cell.Top - (r / 2)), r, "★", BadgeGold);
115	        }
116	    }
117	
118	    private static void DrawBadge(Graphics g, Point topLeft, int radius, string glyph, Color color)
119	    {
120	        var d = radius * 2;
121	        var bounds = new Rectangle(topLeft.X, topLeft.Y, d, d);
122	        using var back = new SolidBrush(BadgeBack);
123	        using var ring = new Pen(color, Math.Max(1f, radius / 6f));
124	        g.FillEllipse(back, bounds);
125	        g.DrawEllipse(ring, bounds);
126	
127	        using var font = new Font("Segoe UI Symbol", Math.Max(6f, radius * 1.25f), FontStyle.Bold, GraphicsUnit.Pixel);
128	        using var brush = new SolidBrush(color);
129	        using var format = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
130	        g.DrawString(glyph, font, brush, new RectangleF(bounds.X, bounds.Y - (radius * 0.08f), bounds.Width, bounds.Height), format);
131	    }
132	}
133	
134	/// <summary>
135	/// Click-through, always-on-top layer covering the capture region that frames every gilded
136	/// rune in place: grey for carried, green for valuable, orange for more valuable, a star
137	/// badge on the top pick. Same window recipe as the debug bounds overlay and the price
138	/// overlay (layered + transparent + no-activate, chroma-keyed background, own STA thread).
139	/// </summary>
140	public sealed class RuneMarkerOverlay(
141	    IPoe2WindowResolutionProvider windowResolutionProvider,
142	    IOptionsMonitor<RunesOptions> runesOptions,
143	    IOptionsMonitor<OcrOptions> ocrOptions,
144	    IOptionsMonitor<AppOptions> appOptions,
145	    ILogger<RuneMarkerOverlay> logger) : IDisposable
146	{
147	    private readonly object _sync = new();
148	    private Thread? _overlayThread;
149	    private RuneMarkerForm? _overlayForm;
150	    private string _lastSignature = string.Empty;
151	
152	    public void Render(LeagueWindowSnapshot snapshot, RuneScoreSheet sheet)
153	    {
154	        ArgumentNullException.ThrowIfNull(snapshot);
155	        ArgumentNullException.ThrowIfNull(sheet);
156	
157	        try
158	        {
159	            var app = appOptions.CurrentValue;
160	            var runes = runesOptions.CurrentValue;
161	            if (!runes.MarkerOverlay || app.AllOverlaysDisabled || ocrOptions.CurrentValue.DebugOverlay)
162	            {
163	                Hide();
164	                return;
165	            }
166	
167	            var captureRegion = windowResolutionProvider.CurrentCaptureRegion;
168	            if (captureRegion is null || !sheet.HasKeys || !snapshot.InterfaceDetected)
169	            {
170	                Hide();
171	                return;
172	            }
173	
174	            var style = RuneMarkerPainter.ParseStyle(runes.CarriedMarkerStyle);
175	            var signature = $"{captureRegion.X},{captureRegion.Y},{captureRegion.Width},{captureRegion.Height}|{style}|{sheet.Signature()}";
176	            if (signature == _lastSignature)
177	                return;
178	
179	            EnsureOverlayThreadStarted();
180	            var form = GetOverlayForm();
181	            if (form is null)
182	            {
183	                logger.LogDebug("RuneMarkerOverlay: form not available, skipping render");
184	                return;
185	            }
186	
187	            _lastSignature = signature;
188	            var markers = RuneMarkerPainter.FromSheet(sheet);
189	            logger.LogDebug("RuneMarkerOverlay: drawing {Count} markers", markers.Count);
190	            form.SafeShow(captureRegion, markers, style);
191	        }
192	        catch (Exception ex)
193	        {
194	            logger.LogError(ex, "Failed to render rune markers: {Context}", ErrorContext.FromException(ex));
195	        }
196	    }
197	
198	    public void Hide()
199	    {
200	        _lastSignature = string.Empty;
201	        GetOverlayForm()?.SafeHide();
202	    }
203	
204	    private void EnsureOverlayThreadStarted()
205	    {
206	        lock (_sync)
207	        {
208	            if (_overlayThread is { IsAlive: true } && _overlayForm is { IsDisposed: false })
209	                return;
210	        }
211	
212	        _overlayThread = OverlayFormRunner.Start<RuneMarkerForm>(
213	            "RuneMarkerOverlay",
214	            _sync,
215	            f => _overlayForm = f,
216	            logger);
217	    }
218	
219	    private RuneMarkerForm? GetOverlayForm()
220	    {
221	        lock (_sync) return _overlayForm is { IsDisposed: false } f ? f : null;
222	    }
223	
224	    public void Dispose()
225	    {
226	        GetOverlayForm()?.SafeClose();
227	    }
228	
229	    private sealed class RuneMarkerForm : Form
230	    {
231	        private static readonly Color TransparencyChroma = Color.FromArgb(1, 2, 3);
232	        private readonly object _stateSync = new();
233	        private IReadOnlyList<RuneMarker> _markers = [];
234	        private CarriedMarkerStyle _style = CarriedMarkerStyle.Slash;
235	        private volatile bool _isHidden = true;
236	
237	        public RuneMarkerForm()
238	        {
239	            FormBorderStyle = FormBorderStyle.None;
240	            ShowInTaskbar = false;
241	            StartPosition = FormStartPosition.Manual;
242	            TopMost = true;
243	            BackColor = TransparencyChroma;
244	            TransparencyKey = TransparencyChroma;
245	            DoubleBuffered = true;
246	            Bounds = new Rectangle(-32000, -32000, 1, 1);
247	        }
248	
249	        protected override bool ShowWithoutActivation => true;
250	
251	        protected override CreateParams CreateParams
252	        {
253	            get
254	            {
255	                var cp = base.CreateParams;
256	                cp.ExStyle |= 0x00000080; // WS_EX_TOOLWINDOW
257	                cp.ExStyle |= 0x00080000; // WS_EX_LAYERED
258	                cp.ExStyle |= 0x00000020; // WS_EX_TRANSPARENT
259	                cp.ExStyle |= 0x08000000; // WS_EX_NOACTIVATE
260	                return cp;
261	            }
262	        }
263	
264	        public void SafeShow(OcrCaptureRegion captureRegion, IReadOnlyList<RuneMarker> markers, CarriedMarkerStyle style)
265	        {
266	            if (IsDisposed) return;
267	            if (InvokeRequired)
268	            {
269	                _isHidden = false;
270	                _ = BeginInvoke(new Action<OcrCaptureRegion, IReadOnlyList<RuneMarker>, CarriedMarkerStyle>(SafeShow), captureRegion, markers, style);
271	                return;
272	            }
273	
274	            _isHidden = false;
275	            lock (_stateSync)
276	            {
277	                _markers = markers;
278	                _style = style;
279	            }
280	
281	            // Badges poke a little past the cells, so give the window a small margin around the region.
282	            const int margin = 12;
283	            Bounds = new Rectangle(captureRegion.X - margin, captureRegion.Y - margin, captureRegion.Width + (2 * margin), Math.Max(1, captureRegion.Height + (2 * margin)));
284	            _offset = new Point(margin, margin);
285	            Invalidate();
286	            PinTopMost();
287	            if (!Visible)
288	            {
289	                Show();
290	                PinTopMost();
291	            }
292	        }
293	
294	        private Point _offset;
295	
296	        public void SafeHide()
297	        {
298	            if (IsDisposed) return;
299	            if (InvokeRequired)
300	            {
301	                if (_isHidden) return;
302	                _isHidden = true;
303	                _ = BeginInvoke(new Action(SafeHide));
304	                return;
305	            }
306	
307	            lock (_stateSync) _markers = [];
308	            Hide();
309	            Bounds = new Rectangle(-32000, -32000, 1, 1);
310	        }
311	
312	        public void SafeClose()
313	        {
314	            if (IsDisposed) return;
315	            if (InvokeRequired)
316	            {
317	                _ = BeginInvoke(new Action(SafeClose));
318	                return;
319	            }
320	            Close();
321	        }
322	
323	        protected override void OnPaint(PaintEventArgs e)
324	        {
325	            base.OnPaint(e);
326	            if (IsDisposed) return;
327	
328	            IReadOnlyList<RuneMarker> markers;
329	            CarriedMarkerStyle style;
330	            lock (_stateSync)
331	            {
332	                markers = _markers;
333	                style = _style;
334	            }
335	
336	            e.Graphics.TranslateTransform(_offset.X, _offset.Y);
337	            RuneMarkerPainter.Paint(e.Graphics, markers, style);
338	        }
339	
340	        protected override void OnDeactivate(EventArgs e)
341	        {
342	            base.OnDeactivate(e);
343	            PinTopMost();
344	        }
345	
346	        protected override void OnShown(EventArgs e)
347	        {
348	            base.OnShown(e);
349	            PinTopMost();
350	        }
351	
352	        private void PinTopMost()
353	        {
354	            if (!IsHandleCreated) return;
355	            _ = NativeMethods.SetWindowPos(Handle, NativeMethods.HWND_TOPMOST, Left, Top, Width, Height,
356	                NativeMethods.SWP_NOACTIVATE | NativeMethods.SWP_NOOWNERZORDER | NativeMethods.SWP_NOSENDCHANGING);
357	        }
358	
359	        private static class NativeMethods
360	        {
361	            public static readonly IntPtr HWND_TOPMOST = new(-1);
362	            public const uint SWP_NOACTIVATE = 0x0010;
363	            public const uint SWP_NOOWNERZORDER = 0x0200;
364	            public const uint SWP_NOSENDCHANGING = 0x0400;
365	
366	            [DllImport("user32.dll", SetLastError = true)]
367	            [return: MarshalAs(UnmanagedType.Bool)]
368	            public static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int x, int y, int cx, int cy, uint uFlags);
369	        }
370	    }
371	}

