  8	namespace RuneshapePriceChecker.App;
  9	
 10	/// <summary>
 11	/// Registers the "reset carried runes" global hotkey (<see cref="RunesOptions.ResetHotkey"/>)
 12	/// on a message-only window living on its own STA thread. No other hotkey machinery exists in
 13	/// the app: the overlay forms are <c>WS_EX_NOACTIVATE</c> and never see keyboard input, and the
 14	/// dashboard's WPF window is not guaranteed to exist. Re-registers when the setting changes; a
 15	/// failed registration logs a warning and leaves the dashboard's reset button as the fallback.
 16	/// </summary>
 17	public sealed class GlobalHotkeyService(
 18	    IOptionsMonitor<RunesOptions> options,
 19	    RuneCatalog catalog,
 20	    ILogger<GlobalHotkeyService> logger) : IHostedService, IDisposable
 21	{
 22	    private const int HotkeyId = 0x5255; // 'RU'
 23	    private Thread? _thread;
 24	    private HotkeyWindow? _window;
 25	    private ApplicationContext? _context;
 26	    private IDisposable? _optionsSubscription;
 27	    private readonly ManualResetEventSlim _ready = new();
 28	
 29	    public Task StartAsync(CancellationToken cancellationToken)
 30	    {
 31	        _thread = new Thread(RunMessageLoop) { IsBackground = true, Name = "GlobalHotkey" };
 32	        _thread.SetApartmentState(ApartmentState.STA);
 33	        _thread.Start();
 34	        _ = _ready.Wait(TimeSpan.FromSeconds(5), cancellationToken);
 35	
 36	        _optionsSubscription = options.OnChange(_ => _window?.RequestReregister());
 37	        return Task.CompletedTask;
 38	    }
 39	
 40	    public Task StopAsync(CancellationToken cancellationToken)
 41	    {
 42	        Dispose();
 43	        return Task.CompletedTask;
 44	    }
 45	
 46	    private void RunMessageLoop()
 47	    {
 48	        try
 49	        {
 50	            _window = new HotkeyWindow(() => options.CurrentValue.ResetHotkey, OnHotkey, logger);
 51	            _window.Register();
 52	            _ready.Set();
 53	            _context = new ApplicationContext();
 54	            Application.Run(_context);
 55	        }
 56	        catch (Exception ex)
 57	        {
 58	            logger.LogWarning(ex, "Global hotkey thread failed: {Context}", ErrorContext.FromException(ex));
 59	            _ready.Set();
 60	        }
 61	        finally
 62	        {
 63	            _window?.DestroyHandle();
 64	            _window = null;
 65	        }
 66	    }
 67	
 68	    private void OnHotkey()
 69	    {
 70	        logger.LogInformation("Reset hotkey pressed — clearing carried succession runes");
 71	        catalog.ResetCarried();
 72	    }
 73	
 74	    public void Dispose()
 75	    {
 76	        _optionsSubscription?.Dispose();
 77	        _optionsSubscription = null;
 78	        try { _context?.ExitThread(); } catch { }
 79	        _ready.Dispose();
 80	    }
 81	
 82	    /// <summary>Parses <c>Ctrl+Alt+R</c>-style text into RegisterHotKey arguments. Empty/whitespace means disabled.</summary>
 83	    public static bool TryParse(string? text, out uint modifiers, out uint virtualKey)
 84	    {
 85	        modifiers = 0;
 86	        virtualKey = 0;
 87	        if (string.IsNullOrWhiteSpace(text)) return false;
 88	
 89	        foreach (var raw in text.Split('+', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
 90	        {
 91	            switch (raw.ToLowerInvariant())
 92	            {
 93	                case "ctrl" or "control": modifiers |= 0x0002; continue;
 94	                case "alt": modifiers |= 0x0001; continue;
 95	                case "shift": modifiers |= 0x0004; continue;
 96	                case "win" or "windows": modifiers |= 0x0008; continue;
 97	            }
 98	
 99	            if (virtualKey != 0) return false; // two non-modifier keys
100	            if (raw.Length == 1 && char.IsLetterOrDigit(raw[0]))
101	            {
102	                virtualKey = char.ToUpperInvariant(raw[0]);
103	                continue;
104	            }
105	            if (Enum.TryParse<Keys>(raw, ignoreCase: true, out var key) && key != Keys.None)
106	            {
107	                virtualKey = (uint)key;
108	                continue;
109	            }
110	            return false;
111	        }
112	
113	        return virtualKey != 0;
114	    }
115	
116	    private sealed class HotkeyWindow : NativeWindow
117	    {
118	        private const int WM_HOTKEY = 0x0312;
119	        private const int WM_APP_REREGISTER = 0x8000 + 0x52;
120	        private static readonly IntPtr HWND_MESSAGE = new(-3);
121	        private readonly Func<string?> _hotkeyText;
122	        private readonly Action _onHotkey;
123	        private readonly ILogger _logger;
124	        private bool _registered;
125	
126	        public HotkeyWindow(Func<string?> hotkeyText, Action onHotkey, ILogger logger)
127	        {
128	            _hotkeyText = hotkeyText;
129	            _onHotkey = onHotkey;
130	            _logger = logger;
131	            CreateHandle(new CreateParams { Parent = HWND_MESSAGE });
132	        }
133	
134	        public void Register()
135	        {
136	            if (_registered)
137	            {
138	                _ = UnregisterHotKey(Handle, HotkeyId);
139	                _registered = false;
140	            }
141	
142	            var text = _hotkeyText();
143	            if (!TryParse(text, out var modifiers, out var vk))
144	            {
145	                if (!string.IsNullOrWhiteSpace(text))
146	                    _logger.LogWarning("Reset hotkey '{Hotkey}' is not a valid key combination; hotkey disabled", text);
147	                return;
148	            }
149	
150	            const uint MOD_NOREPEAT = 0x4000;
151	            if (RegisterHotKey(Handle, HotkeyId, modifiers | MOD_NOREPEAT, vk))
152	            {
153	                _registered = true;
154	                _logger.LogInformation("Reset hotkey registered: {Hotkey}", text);
155	            }
156	            else
157	            {
158	                _logger.LogWarning("Could not register reset hotkey '{Hotkey}' (Win32 error {Error}); use the dashboard button instead", text, Marshal.GetLastWin32Error());
159	            }
160	        }
161	
162	        public void RequestReregister()
163	        {
164	            if (Handle != IntPtr.Zero)
165	                _ = PostMessage(Handle, WM_APP_REREGISTER, IntPtr.Zero, IntPtr.Zero);
166	        }
167	
168	        protected override void WndProc(ref Message m)
169	        {
170	            if (m.Msg == WM_HOTKEY && m.WParam.ToInt32() == HotkeyId)
171	            {
172	                try { _onHotkey(); }
173	                catch (Exception ex) { _logger.LogWarning(ex, "Reset hotkey handler failed"); }
174	                return;
175	            }
176	            if (m.Msg == WM_APP_REREGISTER)
177	            {
178	                Register();
179	                return;
180	            }
181	            base.WndProc(ref m);
182	        }
183	
184	        public override void DestroyHandle()
185	        {
186	            if (_registered && Handle != IntPtr.Zero)
187	            {
188	                _ = UnregisterHotKey(Handle, HotkeyId);
189	                _registered = false;
190	            }
191	            base.DestroyHandle();
192	        }
193	
194	        [DllImport("user32.dll", SetLastError = true)]
195	        [return: MarshalAs(UnmanagedType.Bool)]
196	        private static extern bool RegisterHotKey(IntPtr hWnd, int id, uint fsModifiers, uint vk);
197	
198	        [DllImport("user32.dll", SetLastError = true)]
199	        [return: MarshalAs(UnmanagedType.Bool)]
200	        private static extern bool UnregisterHotKey(IntPtr hWnd, int id);
201	
202	        [DllImport("user32.dll", SetLastError = true)]
203	        [return: MarshalAs(UnmanagedType.Bool)]
204	        private static extern bool PostMessage(IntPtr hWnd, int msg, IntPtr wParam, IntPtr lParam);
205	    }
206	}

