     1	using Microsoft.Extensions.Hosting;
     2	using Microsoft.Extensions.Logging;
     3	using RuneshapePriceChecker.Runes;
     4	
     5	namespace RuneshapePriceChecker.App.Dashboard;
     6	
     7	/// <summary>
     8	/// Maps the <see cref="RuneCatalog"/> into the dashboard's Rune Library views and pushes them
     9	/// whenever the catalog changes (debounced), and wires the library's edits back into the
    10	/// catalog. Lives in the app because the Dashboard assembly cannot reference the catalog.
    11	/// </summary>
    12	public sealed class RuneLibraryPresenter(
    13	    RuneCatalog catalog,
    14	    DashboardService dashboard,
    15	    ILogger<RuneLibraryPresenter> logger) : IHostedService, IDisposable
    16	{
    17	    private static readonly TimeSpan PushDebounce = TimeSpan.FromMilliseconds(250);
    18	    private readonly Dictionary<string, byte[]?> _iconCache = new(StringComparer.OrdinalIgnoreCase);
    19	    private System.Threading.Timer? _pushTimer;
    20	
    21	    public Task StartAsync(CancellationToken cancellationToken)
    22	    {
    23	        dashboard.SetRuneLibraryCallbacks(new RuneLibraryCallbacks
    24	        {
    25	            SetWeight = (runeId, weight) => catalog.SetWeight(runeId, weight),
    26	            Bind = (bindingId, runeId) => catalog.Bind(bindingId, runeId),
    27	            SetCarried = (id, carried) => catalog.SetCarried(id, carried),
    28	            ResetCarried = catalog.ResetCarried,
    29	            Forget = bindingId => catalog.RemoveBinding(bindingId)
    30	        });
    31	        catalog.Changed += SchedulePush;
    32	        Push();
    33	        return Task.CompletedTask;
    34	    }
    35	
    36	    public Task StopAsync(CancellationToken cancellationToken)
    37	    {
    38	        catalog.Changed -= SchedulePush;
    39	        return Task.CompletedTask;
    40	    }
    41	
    42	    private void SchedulePush()
    43	    {
    44	        _pushTimer ??= new System.Threading.Timer(_ => Push(), null, Timeout.Infinite, Timeout.Infinite);
    45	        _ = _pushTimer.Change(PushDebounce, Timeout.InfiniteTimeSpan);
    46	    }
    47	
    48	    private void Push()
    49	    {
    50	        try
    51	        {
    52	            var bindings = catalog.Bindings;
    53	            var boundByRune = bindings.Where(b => b.IsBound)
    54	                .GroupBy(b => b.RuneId!, StringComparer.OrdinalIgnoreCase)
    55	                .ToDictionary(g => g.Key, g => g.OrderByDescending(b => b.SeenCount).First(), StringComparer.OrdinalIgnoreCase);
    56	            var choices = catalog.Runes.Select(r => new RuneChoice(r.Id, r.DisplayName)).ToList();
    57	
    58	            var runes = catalog.Runes.Select(r =>
    59	            {
    60	                boundByRune.TryGetValue(r.Id, out var bound);
    61	                return new RuneLibraryEntryView
    62	                {
    63	                    Id = r.Id,
    64	                    DisplayName = r.DisplayName,
    65	                    Effect = r.Effect,
    66	                    Rare = r.Rare,
    67	                    Tier = r.Tier ?? "",
    68	                    ReferenceIconPng = LoadIcon(r.Icon),
    69	                    BindingId = bound?.Id,
    70	                    Weight = catalog.GetWeight(r.Id),
    71	                    IsCarried = catalog.IsCarried(r.Id),
    72	                    SeenCount = bound?.SeenCount ?? 0,
    73	                    SpritePng = bound?.SpritePngBase64 is { } b64 ? Convert.FromBase64String(b64) : null
    74	                };
    75	            }).ToList();
    76	
    77	            var unbound = bindings.Where(b => !b.IsBound)
    78	                .OrderByDescending(b => b.LastSeenUtc)
    79	                .Select(b => new UnboundSpriteView
    80	                {
    81	                    BindingId = b.Id,
    82	                    SpritePng = b.SpritePngBase64 is { } b64 ? Convert.FromBase64String(b64) : null,
    83	                    SeenCount = b.SeenCount,
    84	                    ColourHint = b.HueBucket is 6 or 7 ? "blue" : b.HueBucket is 8 or 9 ? "purple" : "",
    85	                    CurrentWeight = catalog.UnboundWeight(b.HueBucket),
    86	                    Choices = choices
    87	                }).ToList();
    88	
    89	            dashboard.SetRuneLibrary(runes, unbound);
    90	        }
    91	        catch (Exception ex)
    92	        {
    93	            logger.LogDebug(ex, "Rune library push failed: {Context}", ErrorContext.FromException(ex));
    94	        }
    95	    }
    96	
    97	    private byte[]? LoadIcon(string? icon)
    98	    {
    99	        if (string.IsNullOrEmpty(icon)) return null;
   100	        if (!_iconCache.TryGetValue(icon, out var bytes))
   101	        {
   102	            bytes = RuneCatalog.LoadReferenceIcon(icon);
   103	            _iconCache[icon] = bytes;
   104	        }
   105	        return bytes;
   106	    }
   107	
   108	    public void Dispose()
   109	    {
   110	        _pushTimer?.Dispose();
   111	        _pushTimer = null;
   112	    }
   113	}
