 11	namespace RuneshapePriceChecker.Tests.Runes;
 12	
 13	public class RuneRowScorerTests : IDisposable
 14	{
 15	    private readonly string _dir = Path.Combine(Path.GetTempPath(), "rpc-scorer-" + Guid.NewGuid().ToString("N"));
 16	
 17	    private const string ShippedJson = """
 18	    {"schema":1,"runes":[
 19	      {"id":"opulent","displayName":"Opulent Rune","effect":"","tier":"gold","weight":3.0},
 20	      {"id":"power","displayName":"Power Rune","effect":"","weight":2.0},
 21	      {"id":"bond","displayName":"Bond Rune","effect":"","tier":"purple","weight":1.0}
 22	    ]}
 23	    """;
 24	
 25	    private static readonly IOptionsMonitor<RunesOptions> Options = new StaticOptions(new RunesOptions());
 26	
 27	    private RuneCatalog NewCatalog() => new(Options, NullLogger.Instance, Path.Combine(_dir, "c.json"), ShippedJson);
 28	
 29	    private static RuneKey Key(ulong hash, int x, int y, int hue = 9) => new(hash, hue, new byte[32 * 32 * 3], new Rectangle(x, y, 45, 45));
 30	
 31	    /// <summary>Observes twice so the binding is persisted, then binds it to a rune.</summary>
 32	    private static string Bind(RuneCatalog catalog, RuneKey key, string runeId)
 33	    {
 34	        catalog.Observe(key);
 35	        catalog.Observe(key);
 36	        var id = catalog.FindBinding(key.ShapeHash)!.Id;
 37	        Assert.True(catalog.Bind(id, runeId));
 38	        return id;
 39	    }
 40	
 41	    public void Dispose()
 42	    {
 43	        try { if (Directory.Exists(_dir)) Directory.Delete(_dir, recursive: true); } catch { }
 44	    }
 45	
 46	    [Fact]
 47	    public void ScoresRows_ExcludesCarried_MarksBestAndTopPick()
 48	    {
 49	        using var catalog = NewCatalog();
 50	        // Hashes 32+ bits apart so the shape matcher sees three distinct runes.
 51	        var opulent = Key(0x0F0F0F0F0F0F0F0F, 110, 0);
 52	        var power = Key(0xF0F0F0F0F0F0F0F0, 110, 108);
 53	        var bond = Key(0x00FF00FF00FF00FF, 110, 216);
 54	        Bind(catalog, opulent, "opulent");
 55	        Bind(catalog, power, "power");
 56	        Bind(catalog, bond, "bond");
 57	        catalog.SetCarried("power", true);
 58	
 59	        var snapshot = new LeagueWindowSnapshot(["a", "b", "c"], DateTimeOffset.UtcNow, [61, 169, 277],
 60	            RuneRows:
 61	            [
 62	                new RuneRowKeys(61, [opulent]),
 63	                new RuneRowKeys(169, [power]),
 64	                new RuneRowKeys(277, [bond, power with { CellBounds = new Rectangle(170, 216, 45, 45) }])
 65	            ]);
 66	
 67	        var sheet = new RuneRowScorer(catalog, Options).Score(snapshot);
 68	
 69	        Assert.Equal(3, sheet.Rows.Count);
 70	        Assert.Equal(3.0, sheet.Rows[0].Score);
 71	        Assert.True(sheet.Rows[0].IsBest);
 72	        Assert.Equal(0.0, sheet.Rows[1].Score);
 73	        Assert.False(sheet.Rows[1].IsBest);
 74	        Assert.Equal(1.0, sheet.Rows[2].Score);
 75	
 76	        var opulentScore = sheet.Rows[0].Keys.Single();
 77	        Assert.Equal(RuneMarkerKind.HighValue, opulentScore.Marker);
 78	        Assert.True(opulentScore.IsTopPick);
 79	
 80	        var powerScore = sheet.Rows[1].Keys.Single();
 81	        Assert.True(powerScore.IsCarried);
 82	        Assert.Equal(RuneMarkerKind.Carried, powerScore.Marker);
 83	        Assert.False(powerScore.IsTopPick);
 84	
 85	        var bondScore = sheet.Rows[2].Keys[0];
 86	        Assert.Equal(RuneMarkerKind.Valuable, bondScore.Marker);
 87	        Assert.False(bondScore.IsTopPick);
 88	    }
 89	
 90	    [Fact]
 91	    public void DuplicateRuneInOneRowCountsOnce()
 92	    {
 93	        using var catalog = NewCatalog();
 94	        var bond = Key(0x00FF00FF00FF00FF, 110, 216);
 95	        Bind(catalog, bond, "bond");
 96	
 97	        var twice = new LeagueWindowSnapshot(["a"], DateTimeOffset.UtcNow, [61],
 98	            RuneRows: [new RuneRowKeys(61, [bond, bond with { CellBounds = new Rectangle(170, 216, 45, 45) }])]);
 99	
100	        var sheet = new RuneRowScorer(catalog, Options).Score(twice);
101	        Assert.Equal(1.0, sheet.Rows[0].Score);
102	    }
103	
104	    [Fact]
105	    public void UnboundKeyScoresByHueAndIsFlagged()
106	    {
107	        using var catalog = NewCatalog();
108	        var unseen = Key(0x9999, 110, 0, hue: 6);
109	        var snapshot = new LeagueWindowSnapshot(["a"], DateTimeOffset.UtcNow, [61], RuneRows: [new RuneRowKeys(61, [unseen])]);
110	
111	        var sheet = new RuneRowScorer(catalog, Options).Score(snapshot);
112	        var k = sheet.Rows[0].Keys.Single();
113	        Assert.True(k.IsUnbound);
114	        Assert.Equal(0.5, k.Weight);
115	        Assert.Equal(RuneMarkerKind.Valuable, k.Marker);
116	        Assert.True(k.IsTopPick); // only new rune on screen
117	    }
118	
119	    [Fact]
120	    public void EmptyAndNullRuneRowsProduceNoKeys()
121	    {
122	        using var catalog = NewCatalog();
123	        var scorer = new RuneRowScorer(catalog, Options);
124	        Assert.False(scorer.Score(new LeagueWindowSnapshot(["a"], DateTimeOffset.UtcNow)).HasKeys);
125	        Assert.False(scorer.Score(new LeagueWindowSnapshot(["a"], DateTimeOffset.UtcNow, [61], RuneRows: [new RuneRowKeys(61, [])])).HasKeys);
126	    }
127	
128	    [Fact]
129	    public void SignatureChangesWithCatalogRevisionAndMarker()
130	    {
131	        using var catalog = NewCatalog();
132	        var bond = Key(0x3000, 110, 216);
133	        Bind(catalog, bond, "bond");
134	        var snapshot = new LeagueWindowSnapshot(["a"], DateTimeOffset.UtcNow, [61], RuneRows: [new RuneRowKeys(61, [bond])]);
135	        var scorer = new RuneRowScorer(catalog, Options);
136	
137	        var before = scorer.Score(snapshot).Signature();
138	        catalog.SetCarried("bond", true);
139	        var after = scorer.Score(snapshot).Signature();
140	
141	        Assert.NotEqual(before, after);
142	    }
143	
144	    [Fact]
145	    public void PainterFramesEveryCellInItsColourAndNothingElse()
146	    {
147	        var markers = new List<RuneMarker>
148	        {
149	            new(new Rectangle(20, 20, 45, 45), RuneMarkerKind.Valuable, IsTopPick: false, IsUnbound: false),
150	            new(new Rectangle(120, 20, 45, 45), RuneMarkerKind.HighValue, IsTopPick: true, IsUnbound: false),
151	            new(new Rectangle(220, 20, 45, 45), RuneMarkerKind.Carried, IsTopPick: false, IsUnbound: true),
152	        };
153	
154	        using var bmp = new Bitmap(320, 120, PixelFormat.Format24bppRgb);
155	        using (var g = Graphics.FromImage(bmp))
156	        {
157	            g.Clear(Color.Black);
158	            RuneMarkerPainter.Paint(g, markers, CarriedMarkerStyle.Slash);
159	        }
160	
161	        // A pixel just outside each cell's left edge carries that marker's frame colour.
162	        AssertNear(bmp.GetPixel(18, 42), RuneMarkerPainter.ValuableColor);
163	        AssertNear(bmp.GetPixel(118, 42), RuneMarkerPainter.HighValueColor);
164	        AssertNear(bmp.GetPixel(218, 42), RuneMarkerPainter.CarriedColor);
165	
166	        // Interiors stay untouched (black) away from the slash and badges.
167	        Assert.Equal(Color.Black.ToArgb(), bmp.GetPixel(30, 30).ToArgb());
168	        Assert.Equal(Color.Black.ToArgb(), bmp.GetPixel(130, 55).ToArgb());
169	
170	        // The gap between cells stays untouched.
171	        Assert.Equal(Color.Black.ToArgb(), bmp.GetPixel(90, 42).ToArgb());
172	    }
173	
174	    [Theory]
175	    [InlineData("slash", CarriedMarkerStyle.Slash)]
176	    [InlineData("CROSS", CarriedMarkerStyle.Cross)]
177	    [InlineData("dim", CarriedMarkerStyle.Dim)]
178	    [InlineData("nonsense", CarriedMarkerStyle.Slash)]
179	    [InlineData(null, CarriedMarkerStyle.Slash)]
180	    public void ParseStyle(string? text, CarriedMarkerStyle expected)
181	    {
182	        Assert.Equal(expected, RuneMarkerPainter.ParseStyle(text));
183	    }
184	
185	    [Fact]
186	    public void FrameThicknessScalesWithCellAndNeverBelowTwo()
187	    {
188	        Assert.Equal(3, RuneMarkerPainter.FrameThickness(new Rectangle(0, 0, 45, 45)));
189	        Assert.Equal(2, RuneMarkerPainter.FrameThickness(new Rectangle(0, 0, 20, 20)));
190	        Assert.Equal(6, RuneMarkerPainter.FrameThickness(new Rectangle(0, 0, 90, 90)));
191	    }
192	
193	    private static void AssertNear(Color actual, Color expected)
194	    {
195	        var d = Math.Abs(actual.R - expected.R) + Math.Abs(actual.G - expected.G) + Math.Abs(actual.B - expected.B);
196	        Assert.True(d < 60, $"expected ~{expected}, got {actual}");
197	    }
198	
199	    private sealed class StaticOptions(RunesOptions value) : IOptionsMonitor<RunesOptions>
200	    {
201	        public RunesOptions CurrentValue => value;
202	        public RunesOptions Get(string? name) => value;
203	        public IDisposable? OnChange(Action<RunesOptions, string?> listener) => null;
204	    }
205	}

