 10	namespace RuneshapePriceChecker.Tests.Runes;
 11	
 12	public class RuneCatalogTests : IDisposable
 13	{
 14	    private readonly string _dir = Path.Combine(Path.GetTempPath(), "rpc-runes-" + Guid.NewGuid().ToString("N"));
