  1	using System.Drawing.Imaging;
  2	using System.IO;
  3	using System.Runtime.InteropServices;
  4	using Microsoft.Extensions.Logging.Abstractions;
  5	using Microsoft.Extensions.Options;
  6	using RuneshapePriceChecker.Configuration;
  7	using RuneshapePriceChecker.Contracts;
  8	using RuneshapePriceChecker.OCR;
  9	using RuneshapePriceChecker.Overlay;
 10	using RuneshapePriceChecker.Runes;
 11	using Xunit;
 12	using Xunit.Abstractions;
 13	
 14	namespace RuneshapePriceChecker.Tests.Runes;
 15	
 16	/// <summary>
 17	/// End to end on the real 2560x1440 capture: detector → catalog (bind, carry) → scorer → marker
 18	/// painter. Asserts the markers land on the gilded cells and writes the painted frame next to the
 19	/// test output for eyeballing. Skips when the fixture is absent.
 20	/// </summary>
 21	public class RuneMarkerFixtureTests(ITestOutputHelper output) : IDisposable
 22	{
 23	    private readonly string _dir = Path.Combine(Path.GetTempPath(), "rpc-marker-" + Guid.NewGuid().ToString("N"));
 24	
 25	    public void Dispose()
 26	    {
 27	        try { if (Directory.Exists(_dir)) Directory.Delete(_dir, recursive: true); } catch { }
 28	    }
 29	
 30	    [Fact]
 31	    public void Fixture_MarkersFrameEveryGildedCell_AndTopPickIsOpulent()
 32	    {
 33	        var path = Path.Combine(AppContext.BaseDirectory, "fixtures", "runeicons", "2560x1440", "1 Raw.png");
 34	        if (!File.Exists(path))
 35	        {
 36	            output.WriteLine("SKIP: fixture not found");
 37	            return;
 38	        }
 39	
 40	        using var raw = new Bitmap(path);
 41	        var (rowYs, rowHeights) = DetectTextRows(raw, new OcrOptions());
 42	        var runeRows = new List<RuneRowKeys>();
 43	        for (var i = 0; i < rowYs.Length; i++)
 44	        {
 45	            var searchTop = i == 0 ? 0 : rowYs[i - 1] + rowHeights[i - 1];
 46	            var searchBottom = i == rowYs.Length - 1 ? raw.Height : rowYs[i + 1];
 47	            runeRows.Add(new RuneRowKeys(rowYs[i], RuneIconFingerprinter.ExtractRowKeys(raw, searchTop, searchBottom, rowYs[i], rowHeights[i])));
 48	        }
 49	        Assert.Equal(6, runeRows.Sum(r => r.Keys.Count));
 50	        Assert.All(runeRows.SelectMany(r => r.Keys), k => Assert.True(k.CellBounds.Width > 30 && k.CellBounds.Height > 30, $"cell bounds missing: {k.CellBounds}"));
 51	
 52	        var options = new StaticOptions(new RunesOptions());
 53	        using var catalog = new RuneCatalog(options, NullLogger.Instance, Path.Combine(_dir, "c.json"), RuneCatalog.LoadShippedJson());
 54	
 55	        // Two sightings persist the bindings; then bind the two recurring runes and carry one.
 56	        foreach (var key in runeRows.SelectMany(r => r.Keys)) { catalog.Observe(key); }
 57	        foreach (var key in runeRows.SelectMany(r => r.Keys)) { catalog.Observe(key); }
 58	        Assert.Equal(4, catalog.Bindings.Count); // four distinct gilded runes on this capture
 59	
 60	        var rows13 = catalog.FindBinding(runeRows[1].Keys[0].ShapeHash)!;
 61	        var rows24 = catalog.FindBinding(runeRows[2].Keys[0].ShapeHash)!;
 62	        Assert.Equal(rows13.Id, catalog.FindBinding(runeRows[3].Keys[0].ShapeHash)!.Id);
 63	        Assert.Equal(rows24.Id, catalog.FindBinding(runeRows[4].Keys[0].ShapeHash)!.Id);
 64	        Assert.True(catalog.Bind(rows13.Id, "power"));
 65	        Assert.True(catalog.Bind(rows24.Id, "opulent"));
 66	        catalog.SetCarried("power", true);
 67	
 68	        var snapshot = new LeagueWindowSnapshot(
 69	            Enumerable.Range(0, rowYs.Length).Select(i => $"row {i}").ToList(),
 70	            DateTimeOffset.UtcNow,
 71	            rowYs,
 72	            RuneRows: runeRows);
 73	        var sheet = new RuneRowScorer(catalog, options).Score(snapshot);
 74	
 75	        var markers = RuneMarkerPainter.FromSheet(sheet);
 76	        Assert.Equal(6, markers.Count);
 77	        Assert.Equal(2, markers.Count(m => m.Kind == RuneMarkerKind.Carried));   // rows 1 and 3: Power, carried
 78	        Assert.Equal(2, markers.Count(m => m.Kind == RuneMarkerKind.HighValue)); // rows 2 and 4: Opulent (3)
 79	        Assert.Equal(2, markers.Count(m => m.Kind == RuneMarkerKind.Valuable));  // rows 0 and 5: unbound, weight 1
 80	        Assert.Equal(2, markers.Count(m => m.IsTopPick));
 81	        Assert.All(markers.Where(m => m.IsTopPick), m => Assert.Equal(RuneMarkerKind.HighValue, m.Kind));
 82	        Assert.Equal(2, markers.Count(m => m.IsUnbound));
 83	
 84	        using var painted = (Bitmap)raw.Clone();
 85	        using (var g = Graphics.FromImage(painted))
 86	            RuneMarkerPainter.Paint(g, markers, CarriedMarkerStyle.Slash);
 87	
 88	        // Each frame's left band sits immediately outside its cell.
 89	        foreach (var m in markers)
 90	        {
 91	            var probe = painted.GetPixel(m.Cell.X - 2, m.Cell.Y + (m.Cell.Height / 2));
 92	            var expected = RuneMarkerPainter.ColorFor(m.Kind, CarriedMarkerStyle.Slash);
 93	            var d = Math.Abs(probe.R - expected.R) + Math.Abs(probe.G - expected.G) + Math.Abs(probe.B - expected.B);
 94	            Assert.True(d < 90, $"frame colour missing left of cell {m.Cell}: got {probe}, expected ~{expected}");
 95	        }
 96	
 97	        var outDir = Path.Combine(AppContext.BaseDirectory, "rune-probe-out");
