107	    {
108	        using var masked = OcrImagePreprocessor.KeepBlackAndNeighbors(raw);
109	        using var preprocessed = OcrImagePreprocessor.PreprocessForOcr(masked, options);
110	
111	        var srcRect = new Rectangle(0, 0, preprocessed.Width, preprocessed.Height);
112	        var srcData = preprocessed.LockBits(srcRect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
113	        int stride;
114	        byte[] pixelBytes;
115	        try
116	        {
117	            stride = srcData.Stride;
118	            pixelBytes = new byte[Math.Abs(stride) * preprocessed.Height];
119	            Marshal.Copy(srcData.Scan0, pixelBytes, 0, pixelBytes.Length);
120	        }
121	        finally { preprocessed.UnlockBits(srcData); }
122	
