 1	﻿using Microsoft.Extensions.Logging;
 2	
 3	namespace RuneshapePriceChecker.Overlay;
 4	
 5	internal static class OverlayFormRunner
 6	{
 7	    public static Thread Start<T>(
 8	        string threadName,
 9	        object sync,
10	        Action<T?> setForm,
11	        ILogger? logger = null,
12	        string? timeoutWarning = null)
13	        where T : Form, new()
14	    {
15	        T? localForm = null;
16	        var thread = new Thread(() =>
17	        {
18	            using var f = new T();
19	            _ = f.Handle;
20	            lock (sync) { setForm(f); localForm = f; Monitor.PulseAll(sync); }
21	            Application.Run(f);
22	            lock (sync) setForm(null);
23	        })
24	        {
25	            IsBackground = true,
26	            Name = threadName
27	        };
28	        thread.SetApartmentState(ApartmentState.STA);
29	        thread.Start();
30	
31	        lock (sync)
32	        {
33	            while (localForm is null)
34	                if (!Monitor.Wait(sync, TimeSpan.FromSeconds(5)))
35	                {
36	                    logger?.LogWarning("{FormName} STA form timed out", typeof(T).Name);
37	                    setForm(null);
38	                    return thread;
39	                }
40	        }
41	
42	        return thread;
43	    }
44	}

